import com.spinplayer.app.LyricsText;import java.nio.charset.*;public class LyricsTextTest{public static void main(String[]args)throws Exception{String s="Оригинальная строка\nВторая строка";for(String enc:new String[]{"UTF-8","UTF-16","windows-1251"})if(!s.equals(LyricsText.decode(s.getBytes(enc))))throw new AssertionError(enc);if(!LyricsText.synced("[01:02.500]Fixture")||LyricsText.synced(s))throw new AssertionError("format");for(String bad:new String[]{"   ","abc\u0000def"}){try{LyricsText.validate(bad);throw new AssertionError("accepted invalid file");}catch(java.io.IOException ok){}}System.out.println("PASS: UTF-8, UTF-16, Windows-1251, blank/binary rejection, timed/plain detection");}}
